create table if not exists public.digital_page_payment_events (id uuid primary key default gen_random_uuid(),digital_page_order_id uuid not null references public.digital_page_orders(id) on delete cascade,provider text not null,external_event_id text not null unique,event_type text not null,status text not null,signature_verified boolean not null,raw_payload jsonb not null,created_at timestamptz not null default now()); alter table public.digital_page_payment_events enable row level security; revoke all on public.digital_page_payment_events from anon,authenticated;